// Giants brand colors pulled from the official style guide
import { CanvasTexture, Color, Mesh, MeshStandardMaterial, Object3D, SRGBColorSpace, TextureLoader } from 'three'

export const GIANTS = {
  orange: '#FD5A1E',
  black: '#000000',
  cream: '#F5E8C8',
  grey: '#B4B9BE',
}

const textureLoader = new TextureLoader()

// lazily loaded so the textures aren't fetched until a fielder actually needs them
let homeTex: ReturnType<TextureLoader['load']> | null = null
let awayTex: ReturnType<TextureLoader['load']> | null = null

function loadGiantsTextures() {
  if (!homeTex) {
    homeTex = textureLoader.load(`${process.env.PUBLIC_URL}/textures/GiantsHome_BaseColor.png`)
    homeTex.flipY = false
    homeTex.colorSpace = SRGBColorSpace
  }
  if (!awayTex) {
    awayTex = textureLoader.load(`${process.env.PUBLIC_URL}/textures/GiantsAway_BaseColor.png`)
    awayTex.flipY = false
    awayTex.colorSpace = SRGBColorSpace
  }
  return { homeTex, awayTex }
}

// swaps the body texture on a PlayerControls instance to home whites or away grey
export function applyGiantsJersey(
  player: {
    bodyMaterial: MeshStandardMaterial
    bodyMesh: Mesh
    rightHandMesh: Mesh
    leftHandMesh: Mesh
    hatMesh?: Mesh
    teamType?: 'away' | 'home'
  },
  style: 'home' | 'away' = 'home',
) {
  const { homeTex, awayTex } = loadGiantsTextures()
  const tex = style === 'home' ? homeTex : awayTex
  player.bodyMaterial.map = tex
  player.bodyMaterial.color = new Color('#ffffff')
  player.bodyMaterial.needsUpdate = true
  if (player.hatMesh && player.hatMesh.material instanceof MeshStandardMaterial) {
    player.hatMesh.material = player.bodyMaterial
  }
}

// recolors the generic park model to look like Oracle Park
// walls go dark green, scoreboards get an orange glow, tan concrete shifts to brick
export function applyOracleParkGiantsTheme(scene: Object3D) {
  const giantsOrange = new Color(GIANTS.orange)
  const brick = new Color('#8B4513')
  const darkGreen = new Color('#1a3a2a')

  scene.traverse((child) => {
    if (!(child instanceof Mesh)) return
    const mats = Array.isArray(child.material) ? child.material : [child.material]
    mats.forEach((mat) => {
      if (!(mat instanceof MeshStandardMaterial)) return
      const name = `${child.name} ${mat.name}`.toLowerCase()

      if (name.includes('wall') || name.includes('fence') || name.includes('pad')) {
        mat.color = darkGreen
        mat.needsUpdate = true
      }
      if (name.includes('screen') || name.includes('score') || name.includes('sign')) {
        mat.emissive = giantsOrange
        mat.emissiveIntensity = 0.15
        mat.needsUpdate = true
      }
      if (mat.color && mat.map == null) {
        const c = mat.color
        if (c.r > 0.55 && c.g > 0.5 && c.b > 0.4 && Math.abs(c.r - c.g) < 0.15) {
          mat.color = brick.clone().lerp(c, 0.55)
          mat.needsUpdate = true
        }
      }
    })
  })
}

// draws a scoreboard texture on a canvas so the in-game screen shows Giants branding
export function createGiantsScoreboardTexture() {
  const canvas = document.createElement('canvas')
  canvas.width = 1024
  canvas.height = 512
  const ctx = canvas.getContext('2d')!

  ctx.fillStyle = '#0a0a0a'
  ctx.fillRect(0, 0, canvas.width, canvas.height)

  ctx.fillStyle = GIANTS.orange
  ctx.fillRect(0, 0, canvas.width, 72)
  ctx.fillStyle = '#000'
  ctx.font = 'bold 36px sans-serif'
  ctx.textAlign = 'center'
  ctx.fillText('ORACLE PARK', canvas.width / 2, 48)

  ctx.fillStyle = GIANTS.orange
  ctx.font = 'bold 84px sans-serif'
  ctx.fillText('SAN FRANCISCO', canvas.width / 2, 200)
  ctx.fillStyle = '#fff'
  ctx.font = 'bold 96px sans-serif'
  ctx.fillText('GIANTS', canvas.width / 2, 300)

  ctx.fillStyle = '#888'
  ctx.font = '28px sans-serif'
  ctx.fillText('SHIFT REPLAY  ·  SMT CHALLENGE', canvas.width / 2, 420)

  const tex = new CanvasTexture(canvas)
  tex.colorSpace = SRGBColorSpace
  tex.needsUpdate = true
  return tex
}
