// rough radial approximation of Oracle Park's outfield wall shape
// corners pull inward faster on the right field side than left
function oracleWallRadius(dirX: number, dirZ: number): number {
  const ang = Math.atan2(dirX, dirZ)
  const cornerT = Math.min(Math.abs(ang) / (Math.PI * 0.28), 1)
  if (ang >= 0) return 128 - cornerT * cornerT * 23
  return 128 - cornerT * cornerT * 35
}

// keeps fielder positions and camera from clipping through the outfield wall
function clampInsidePark(x: number, z: number, margin = 0.5): { x: number; z: number } {
  const r = Math.hypot(x, z)
  if (r < 1e-6) return { x, z }
  const maxR = oracleWallRadius(x / r, z / r) - margin
  if (r <= maxR) return { x, z }
  const s = maxR / r
  return { x: x * s, z: z * s }
}

