// linearly interpolates between recorded position samples at an arbitrary time
function lerpTrack(track: VecSample[], tMs: number): Vector3 {
  if (track.length === 0) return new Vector3()
  if (tMs <= track[0].t_ms) return new Vector3(track[0].x, track[0].y, track[0].z)
  if (tMs >= track[track.length - 1].t_ms) {
    const last = track[track.length - 1]
    return new Vector3(last.x, last.y, last.z)
  }
  for (let i = 1; i < track.length; i++) {
    if (tMs <= track[i].t_ms) {
      const a = track[i - 1]
      const b = track[i]
      const u = (tMs - a.t_ms) / (b.t_ms - a.t_ms)
      return new Vector3(
        a.x + (b.x - a.x) * u,
        a.y + (b.y - a.y) * u,
        a.z + (b.z - a.z) * u,
      )
    }
  }
  const last = track[track.length - 1]
  return new Vector3(last.x, last.y, last.z)
}

// flattens the full track to ground level for drawing the route line
// snaps to the catch point if the fielder ended up close enough
function trackToRoutePoints(
  track: VecSample[],
  endPoint?: Vector3,
): Vector3[] {
  const pts = track.map(s => new Vector3(s.x, 0.08, s.z))
  if (endPoint && track.length > 0) {
    const last = track[track.length - 1]
    const dist = Math.hypot(endPoint.x - last.x, endPoint.z - last.z)
    if (dist < 3.5) pts.push(new Vector3(endPoint.x, 0.08, endPoint.z))
  }
  return pts
}

// same as trackToRoutePoints but only up to the current playback time
// used for the animated trail that grows as the play unfolds
function routePointsUpTo(
  track: VecSample[],
  tMs: number,
  endPoint?: Vector3,
  durationMs?: number,
): Vector3[] {
  if (track.length === 0) return []
  const pts: Vector3[] = []
  for (const s of track) {
    if (s.t_ms > tMs) break
    pts.push(new Vector3(s.x, 0.08, s.z))
  }
  const cur = lerpTrack(track, tMs)
  pts.push(new Vector3(cur.x, 0.08, cur.z))
  if (endPoint && durationMs != null && durationMs > 0 && tMs >= durationMs - 20) {
    const last = track[track.length - 1]
    const dist = Math.hypot(endPoint.x - last.x, endPoint.z - last.z)
    if (dist < 3.5) pts.push(new Vector3(endPoint.x, 0.08, endPoint.z))
  }
  return pts.length >= 2 ? pts : pts.length === 1 ? [pts[0], pts[0].clone()] : []
}

// Build the red ghost's path from the green fielder's recorded track.
// We do not have separate tracking from the average start.
// Instead take each sample on the real run and place it on a new line
// from the league-average start toward the landing spot.
// Keep a little sideways bend so it still looks like a real route.
function morphTrackToGhost(
  track: VecSample[],
  ghostStart: Vector3,
  catchPoint: Vector3,
): Vector3[] {
  const n = Math.max(track.length, 2)
  if (track.length < 2) {
    return [
      new Vector3(ghostStart.x, 0.08, ghostStart.z),
      new Vector3(catchPoint.x, 0.08, catchPoint.z),
    ]
  }

  // actual start to actual end is the "along" axis of the real run
  const p0 = new Vector3(track[0].x, 0, track[0].z)
  const pN = new Vector3(track[track.length - 1].x, 0, track[track.length - 1].z)
  const srcDir = pN.clone().sub(p0)
  const srcLen = Math.max(srcDir.length(), 1e-3)
  srcDir.multiplyScalar(1 / srcLen)

  const lateral = new Vector3(-srcDir.z, 0, srcDir.x)

  return track.map((s, i) => {
    const u = i / (n - 1)
    const p = new Vector3(s.x, 0, s.z)
    const along = p.clone().sub(p0).dot(srcDir)
    const side = p.clone().sub(p0).dot(lateral)
    // same fraction along the real run but on the avg-start to ball line
    const linearDst = ghostStart.clone().lerp(catchPoint, Math.min(1, Math.max(0, along / srcLen)))
    const bend = Math.max(-3, Math.min(3, side * 0.35))
    const dstDir = catchPoint.clone().sub(ghostStart)
    dstDir.y = 0
    if (dstDir.lengthSq() > 1e-6) dstDir.normalize()
    else dstDir.copy(srcDir)
    const dstLateral = new Vector3(-dstDir.z, 0, dstDir.x)
    return new Vector3(
      linearDst.x + dstLateral.x * bend,
      0.08,
      linearDst.z + dstLateral.z * bend,
    )
  })
}

// walks a polyline by arc length and returns the position at fraction u
function samplePolyline(points: Vector3[], u: number): Vector3 {
  if (points.length === 0) return new Vector3()
  if (points.length === 1 || u <= 0) return points[0].clone()
  if (u >= 1) return points[points.length - 1].clone()

  let total = 0
  const segLens: number[] = []
  for (let i = 1; i < points.length; i++) {
    const len = points[i].distanceTo(points[i - 1])
    segLens.push(len)
    total += len
  }
  if (total < 1e-6) return points[0].clone()

  let target = u * total
  for (let i = 0; i < segLens.length; i++) {
    const len = segLens[i]
    if (target <= len || i === segLens.length - 1) {
      const s = len < 1e-6 ? 1 : Math.min(1, target / len)
      return points[i].clone().lerp(points[i + 1], s)
    }
    target -= len
  }
  return points[points.length - 1].clone()
}

// returns only the portion of a polyline up to arc-length fraction u
// used to grow the ghost trail over time at the right speed
function polylineUpTo(points: Vector3[], u: number): Vector3[] {
  if (points.length < 2) return points.map(p => p.clone())
  const end = samplePolyline(points, Math.min(1, Math.max(0, u)))
  if (u <= 0) return [points[0].clone(), points[0].clone()]

  let total = 0
  for (let i = 1; i < points.length; i++) total += points[i].distanceTo(points[i - 1])
  const target = Math.min(1, Math.max(0, u)) * total

  const pts: Vector3[] = [points[0].clone()]
  let acc = 0
  for (let i = 1; i < points.length; i++) {
    const len = points[i].distanceTo(points[i - 1])
    if (acc + len >= target - 1e-6) {
      pts.push(end)
      return pts
    }
    acc += len
    pts.push(points[i].clone())
  }
  pts.push(end)
  return pts
}

// gathers ball positions up to tMs for the yellow trail behind the ball
function ballTrailPoints(track: VecSample[], tMs: number): Vector3[] {
  if (track.length === 0) return []
  const pts: Vector3[] = []
  for (const s of track) {
    if (s.t_ms > tMs) break
    pts.push(new Vector3(s.x, s.y, s.z))
  }
  const cur = lerpTrack(track, tMs)
  pts.push(cur.clone())
  return pts.length >= 2 ? pts : []
}

// tries a few known bone names to find the head so we can tilt it toward the ball
function findHeadBone(player: PlayerControls): Bone | null {
  const skeleton = player.bodyMesh?.skeleton
  if (!skeleton) return null
  for (const name of ['spine.006', 'neck', 'spine.002', 'Head', 'head']) {
    const bone = skeleton.getBoneByName(name)
    if (bone) return bone
  }
  return skeleton.bones.find(b => /head|neck|spine\.006/i.test(b.name)) ?? null
}

// rotates the whole body toward the landing spot, then tilts the head to track the ball
function orientFielderTowardBall(
  player: PlayerControls,
  landing: Vector3,
  ballPos: Vector3,
) {
  player.scene.lookAt(landing.x, 0, landing.z)

  const head = findHeadBone(player)
  if (!head) return

  const headWorld = new Vector3()
  head.getWorldPosition(headWorld)
  const toBall = ballPos.clone().sub(headWorld)
  if (toBall.lengthSq() < 0.01) return

  const parent = head.parent
  if (!parent) return

  const inv = parent.matrixWorld.clone().invert()
  const localTarget = ballPos.clone().applyMatrix4(inv)
  head.lookAt(localTarget)
}

