// Main replay. Loads the play list, handles play pause replay, and hosts the 3D scene.
export default function ShiftReplayView({ onOpenGuide, active = true }: { onOpenGuide?: () => void; active?: boolean }) {
  const [playIndex, setPlayIndex] = useState<PlayIndexEntry[]>([])
  const [selectedId, setSelectedId] = useState<string | null>(null)
  const [play, setPlay] = useState<ShiftPlayData | null>(null)
  const [error, setError] = useState<string | null>(null)
  const [isPlaying, setIsPlaying] = useState(false)
  const [isDone, setIsDone] = useState(false)
  const [clockMs, setClockMs] = useState(0)
  const [phase, setPhase] = useState<'idle' | 'running' | 'caught'>('idle')
  const catchSoundPlayed = useRef(false)
  const holdUntilRef = useRef<number | null>(null)

  // fetch the play list once on mount
  useEffect(() => {
    fetch(`${process.env.PUBLIC_URL}/plays/index.json`)
      .then(r => {
        if (!r.ok) throw new Error(`Failed to load plays index (${r.status}). Run: python code/export_play_json.py --all`)
        return r.json()
      })
      .then((data: { plays: PlayIndexEntry[] }) => {
        setPlayIndex(data.plays)
        if (data.plays.length) setSelectedId(data.plays[0].id)
      })
      .catch(e => setError(String(e)))
  }, [])

  // whenever the user picks a new play, fetch its JSON and auto-start it
  useEffect(() => {
    if (!selectedId || !playIndex.length) return
    const entry = playIndex.find(p => p.id === selectedId)
    if (!entry) return

    setIsPlaying(false)
    setPlay(null)
    setError(null)

    fetch(`${process.env.PUBLIC_URL}/plays/${entry.file}`)
      .then(r => {
        if (!r.ok) throw new Error(`Failed to load ${entry.file} (${r.status})`)
        return r.json()
      })
      .then((data: ShiftPlayData) => {
        setPlay(data)
        setPhase('idle')
        setClockMs(0)
        setIsDone(false)
        catchSoundPlayed.current = false
        holdUntilRef.current = null
        setIsPlaying(true)
      })
      .catch(e => setError(String(e)))
  }, [selectedId, playIndex])

  const resetToStart = useCallback(() => {
    setClockMs(0)
    setPhase('idle')
    setIsDone(false)
    catchSoundPlayed.current = false
    holdUntilRef.current = null
  }, [])

  const handlePlay = useCallback(() => {
    if (isDone) resetToStart()
    setIsPlaying(true)
  }, [isDone, resetToStart])

  const handlePause = useCallback(() => {
    setIsPlaying(false)
  }, [])

  const handleReplay = useCallback(() => {
    resetToStart()
    setIsPlaying(false)
  }, [resetToStart])

  // Playback clock. idle holds briefly at the start, then running, then caught.
  // After the catch we pause so the glove animation can finish before stopping.
  useEffect(() => {
    if (!play || !isPlaying || !active) return

    let raf = 0
    let last = performance.now()
    const duration = play.duration_ms
    const INTRO_MS = 400
    const HOLD_MS = 1600

    const tick = (now: number) => {
      const dt = now - last
      last = now

      setClockMs(prev => {
        if (prev === 0 && phase === 'idle') {
          if (holdUntilRef.current == null) {
            holdUntilRef.current = now + INTRO_MS
            return 0
          }
          if (now < holdUntilRef.current) return 0
          holdUntilRef.current = null
          setPhase('running')
          return 0
        }

        if (phase === 'caught') {
          if (holdUntilRef.current != null && now >= holdUntilRef.current) {
            holdUntilRef.current = null
            setIsPlaying(false)
            setIsDone(true)
          }
          return duration
        }

        const next = Math.min(prev + dt, duration)
        if (next >= duration) {
          setPhase('caught')
          if (!catchSoundPlayed.current) {
            catchSoundPlayed.current = true
            mitCatchSound.currentTime = 0
            mitCatchSound.play().catch(() => {})
          }
          holdUntilRef.current = now + HOLD_MS
          return duration
        }
        if (phase !== 'running') setPhase('running')
        return next
      })

      raf = requestAnimationFrame(tick)
    }

    raf = requestAnimationFrame(tick)
    return () => cancelAnimationFrame(raf)
  }, [play, isPlaying, phase, active])

  if (error) {
    return (
      <div className={styles.absoluteCentered} style={{ textAlign: 'center', padding: 24 }}>
        <div>{error}</div>
        <a href={`#${BASE_PATH || '/'}`} style={{ display: 'block', marginTop: 12 }}>Back</a>
      </div>
    )
  }

  if (!play || !selectedId) {
    return <div className={styles.absoluteCentered}>Loading replays…</div>
  }

  const m = play.metrics
  // feet saved = distance from avg start minus distance from actual start
  const feetSaved =
    m.actual_distance != null && m.avg_distance != null
      ? (m.avg_distance - m.actual_distance).toFixed(1)
      : '—'

  return (
    <div className="App" style={{ height: '100vh', display: 'flex', flexDirection: 'column', background: '#0b0f14', color: 'white' }}>
      <div style={{ flex: 1, minHeight: 0, position: 'relative' }}>
        <div style={{
          position: 'absolute',
          top: 12,
          left: 12,
          zIndex: 2,
          display: 'flex',
          flexDirection: 'column',
          gap: 10,
        }}>
          <label style={{ display: 'flex', flexDirection: 'column', gap: 4, fontSize: 11, opacity: 0.9 }}>
            <select
              aria-label="Choose a replay"
              value={selectedId}
              onChange={e => setSelectedId(e.target.value)}
              style={{
                minWidth: 340,
                maxWidth: 480,
                padding: '8px 10px',
                background: '#141a22',
                color: '#fff',
                border: '1px solid rgb(210, 210, 210)',
                fontSize: 13,
                fontFamily: 'inherit',
              }}
            >
              {playIndex.map((p, i) => (
                <option key={p.id} value={p.id}>
                  {`#${i + 1}, ${p.fielder_abbr}, +${p.prob_diff.toFixed(1)} pt advantage, ${p.feet_saved} ft saved, ${p.actual_catch_prob}% vs ${p.catch_prob_from_avg}%`}
                </option>
              ))}
            </select>
          </label>
  
          <div style={{
            background: 'rgba(255, 255, 255, 0.90)',
            padding: '14px 13px',
            display: 'flex',
            flexDirection: 'column',
            gap: 10,
            width: 210,
          }}>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
              <LegendChip color={ACTUAL_GREEN} label="ACTUAL START" sub={m.actual_catch_prob != null ? `${m.actual_catch_prob}%` : undefined} />
              <LegendChip color={AVERAGE_RED} label="GHOST START" sub={m.catch_prob_from_avg != null ? `${m.catch_prob_from_avg}%` : undefined} />
            </div>
  
            <div style={{ height: 1, background: 'rgb(0, 0, 0)' }} />
  
            <div style={{ display: 'flex', gap: 10, fontVariantNumeric: 'tabular-nums' }}>
              <Stat label="PT ADVANTAGE" value={m.prob_diff != null ? `+${m.prob_diff}` : '—'} />
              <Stat label="FEET SAVED" value={feetSaved} />
            </div>
          </div>
        </div>
  
        <div style={{
          position: 'absolute',
          top: 12,
          right: 12,
          zIndex: 2,
          display: 'flex',
          gap: 8,
        }}>
          {onOpenGuide && (
            <button type="button" onClick={onOpenGuide} style={btnSecondary}>How it works</button>
          )}
          {isPlaying ? (
            <button type="button" onClick={handlePause} style={btnSecondary}>Pause</button>
          ) : (
            <button type="button" onClick={handlePlay} style={btnStyle}>Play</button>
          )}
          <button type="button" onClick={handleReplay} style={btnSecondary}>Replay</button>
        </div>
  
        <Canvas
          key={selectedId}
          shadows="percentage"
          camera={{ position: [0, 2.6, -10], near: 0.1, far: 800, fov: 55 }}
          dpr={Math.min(window.devicePixelRatio, 1.5)}
          style={{ width: '100%', height: '100%' }}
        >
          <UnifiedShiftScene
            play={play}
            clockMs={clockMs}
            phase={phase}
            isPlaying={isPlaying}
          />
        </Canvas>
        <p style={{
          position: 'absolute',
          bottom: 8,
          left: 12,
          right: 12,
          zIndex: 2,
          margin: 0,
          fontSize: 11,
          lineHeight: 1.3,
          color: 'rgba(255,255,255,0.72)',
          pointerEvents: 'none',
        }}>
          Shirin Alapati · Ethan Nepo · Jacob Crumley · San José State University · Team 227
          {' · '}
          SMT Data Challenge tracking
          {' · '}
          3D assets adapted from Solomon Gumball’s baseball-sim (MIT)
        </p>
      </div>
    </div>
  )
}

function Stat({ label, value, accent }: { label: string; value: string; accent?: string }) {
  return (
    <div style={{ 
      textAlign: 'center',
      padding: '0px 5px', 
      }}>
      <div style={{ fontSize: 50, opacity: 0.95, color: 'black'}}>{value}</div>
      <div style={{ fontSize: 15, fontWeight: 700, color: 'black'}}>{label}</div>
    </div>
  )
}

function LegendChip({ color, label, sub }: { color: string; label: string; sub?: string }) {
  return (
    <div style={{
      padding: '4px 10px',
      display: 'flex',
      flexDirection: 'column',
      gap: 0
    }}>
      <div style={{ fontSize: 20, letterSpacing: 1.2, color, fontWeight: 700, lineHeight: 1.2 }}>{label}</div>
      <div style={{ fontSize: 50, opacity: 0.95, color: 'black', lineHeight: 1.1 }}>{sub}</div>
      <div style={{ fontSize: 13, fontWeight: 700, color: 'black', lineHeight: 1.3 }}>EST. CATCH PROB.</div>
    </div>
  )
}

function StartMarker({ position, color }: { position: Vector3; color: string }) {
  return (
    <group position={[position.x, 0.05, position.z]}>
      <mesh rotation={[-Math.PI / 2, 0, 0]}>
        <circleGeometry args={[1.35, 40]} />
        <meshBasicMaterial color={color} transparent opacity={0.35} depthTest={false} />
      </mesh>
      <mesh rotation={[-Math.PI / 2, 0, 0]}>
        <ringGeometry args={[1.2, 1.75, 40]} />
        <meshBasicMaterial color={color} transparent opacity={0.95} depthTest={false} />
      </mesh>
      <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, -0.01, 0]}>
        <ringGeometry args={[0.4, 0.8, 32]} />
        <meshBasicMaterial color={color} transparent opacity={0.85} depthTest={false} />
      </mesh>
    </group>
  )
}

function RouteTrail({
  points,
  color,
  opacity = 0.95,
  lineWidth = 3,
  trailKey,
}: {
  points: Vector3[]
  color: string
  opacity?: number
  lineWidth?: number
  trailKey?: string
}) {
  if (points.length < 2) return null
  return (
    <Line
      key={trailKey ?? `${points.length}-${color}`}
      points={points}
      color={color}
      lineWidth={lineWidth}
      transparent
      opacity={opacity}
      depthTest={false}
    />
  )
}

function FielderLabel({ label, color }: { label: string; color: string }) {
  return (
    <Html center position={[0, 2.35, 0]} style={{ pointerEvents: 'none' }}>
      <div style={{
        background: 'rgba(255,255,255,0.90)',
        color: '#111',
        padding: '4px 10px',
        borderRadius: 999,
        fontSize: 12,
        fontWeight: 700,
        whiteSpace: 'nowrap',
        border: `2px solid ${color}`,
        boxShadow: '0 2px 8px rgba(0,0,0,0.35)',
      }}>
        {label}
      </div>
    </Html>
  )
}

// The 3D scene for one play. Draws both fielders, trails, ball, park, and camera.
function UnifiedShiftScene({
  play,
  clockMs,
  phase,
  isPlaying,
}: {
  play: ShiftPlayData
  clockMs: number
  phase: 'idle' | 'running' | 'caught'
  isPlaying: boolean
}) {
  const parkGltf = useLoader(GLTFLoader, `${process.env.PUBLIC_URL}/assets/oracle-park.glb`)
  const parkScene = useMemo(() => {
    const cloned = parkGltf.scene.clone(true)
    applyOracleParkGiantsTheme(cloned)
    const screen = cloned.getObjectByName('Screen') as Mesh | undefined
    if (screen) {
      screen.material = new MeshBasicMaterial({ map: createGiantsScoreboardTexture() })
    }
    return cloned
  }, [parkGltf.scene])

  const playerGLTF = useLoader(GLTFLoader, `${process.env.PUBLIC_URL}/assets/player.glb`)
  const ballGltf = useLoader(GLTFLoader, `${process.env.PUBLIC_URL}/assets/ball.glb`)
  const baseball = useMemo(() => ballGltf.scene.clone(true), [ballGltf.scene])
  const freeBallGroup = useRef<Group>(null)
  const ballCaught = useRef(false)
  const lightRef = useRef<DirectionalLight>(null)
  const lightTargetRef = useRef<Object3D>(null)

  const actualFielder = useMemo(() => {
    const controls = new PlayerControls(playerGLTF, 'defense', play.fielder_abbr, 'home')
    applyGiantsJersey(controls, 'home')
    return controls
  }, [playerGLTF, play.fielder_abbr])

  const averageFielder = useMemo(() => {
    const controls = new PlayerControls(playerGLTF, 'defense', play.fielder_abbr, 'away')
    applyGiantsJersey(controls, 'away')
    controls.setOpacity(0.80)
    return controls
  }, [playerGLTF, play.fielder_abbr])

  const actualStart = useMemo(() => {
    const s = play.fielder_track[0]
    return new Vector3(s.x, 0, s.z)
  }, [play.fielder_track])

  const ghostStart = useMemo(
    () => new Vector3(play.ghost_start.x, 0, play.ghost_start.z),
    [play.ghost_start],
  )

  const catchPoint = useMemo(
    () => new Vector3(play.catch_point.x, 0, play.catch_point.z),
    [play.catch_point],
  )

  const actualEnd = useMemo(() => {
    const s = play.fielder_track[play.fielder_track.length - 1]
    const clamped = clampInsidePark(s.x, s.z, 0.4)
    return new Vector3(clamped.x, 0, clamped.z)
  }, [play.fielder_track])

  const landingPoint = useMemo(() => {
    const dist = actualEnd.distanceTo(catchPoint)
    return dist < 3.5 ? catchPoint.clone() : actualEnd.clone()
  }, [actualEnd, catchPoint])

  // Cap how far the ghost runs. actual_distance / avg_distance is under 1
  // when the real start was closer so the red fielder stops short of the ball.
  const ghostReachFrac = useMemo(() => {
    const actual = play.metrics.actual_distance
    const avg = play.metrics.avg_distance
    if (actual == null || avg == null || avg <= 0) return 0.55
    return Math.min(0.88, Math.max(0.2, actual / avg))
  }, [play.metrics.actual_distance, play.metrics.avg_distance])

  const ghostRoute = useMemo(
    () => morphTrackToGhost(play.fielder_track, ghostStart, landingPoint),
    [play.fielder_track, ghostStart, landingPoint],
  )

  // Hold both fielders until bat contact then start moving.
  // Ghost progress fills the hang-time window then is scaled by ghostReachFrac.
  const tMs = Math.min(clockMs, play.duration_ms)
  const contactMs = Math.max(0, Math.min(play.contact_ms ?? 0, play.duration_ms))
  const postContactMs = Math.max(0, tMs - contactMs)
  const moveWindowMs = Math.max(1, play.duration_ms - contactMs)
  const ghostProgress = (postContactMs / moveWindowMs) * ghostReachFrac
  const fieldersMoving = tMs >= contactMs && phase !== 'idle'

  const actualFullRoute = useMemo(
    () => trackToRoutePoints(play.fielder_track, landingPoint),
    [play.fielder_track, landingPoint],
  )

  const actualTraveledRoute = useMemo(() => {
    if (!fieldersMoving) return []
    const done = phase === 'caught' || tMs >= play.duration_ms - 20
    if (done) return actualFullRoute
    return routePointsUpTo(play.fielder_track, tMs, landingPoint, play.duration_ms)
  }, [play.fielder_track, play.duration_ms, tMs, phase, landingPoint, actualFullRoute, fieldersMoving])

  const averageTraveledRoute = useMemo(
    () => (fieldersMoving ? polylineUpTo(ghostRoute, ghostProgress) : []),
    [ghostRoute, ghostProgress, fieldersMoving],
  )

  const ballTrail = useMemo(
    () => ballTrailPoints(play.ball_track, tMs),
    [play.ball_track, tMs],
  )

  const lastPhase = useRef(phase)
  const lastActualAnim = useRef('')
  const lastAverageAnim = useRef('')

  useEffect(() => {
    actualFielder.setGloveHand('L')
    averageFielder.setGloveHand('L')
    actualFielder.scene.position.set(actualStart.x, 0, actualStart.z)
    averageFielder.scene.position.set(ghostStart.x, 0, ghostStart.z)
    actualFielder.scene.lookAt(landingPoint.x, 0, landingPoint.z)
    averageFielder.scene.lookAt(landingPoint.x, 0, landingPoint.z)
    actualFielder.setAnimationState('StandingNeutral')
    averageFielder.setAnimationState('StandingNeutral')
    ballCaught.current = false
    freeBallGroup.current?.attach(baseball)
    const ball0 = play.ball_track[0]
    baseball.position.set(ball0.x, ball0.y, ball0.z)
    lastActualAnim.current = ''
    lastAverageAnim.current = ''
  }, [actualFielder, averageFielder, actualStart, ghostStart, landingPoint, catchPoint, play, baseball])

  useEffect(() => {
    if (lightRef.current) lightRef.current.shadow.bias = -0.00003
  }, [])

  const light = useMemo(() => {
    const POSITION = new Vector3(-30, 40, 10)
    const DIRECTION = new Vector3(1, -1, 0.4).normalize()
    return {
      POSITION,
      TARGET: POSITION.clone().add(DIRECTION.multiplyScalar(40)),
    }
  }, [])

  useFrame((_, delta) => {
    if (isPlaying) {
      actualFielder.update(delta)
      averageFielder.update(delta)
    }

    const t = Math.min(clockMs, play.duration_ms)
    const ballPos = lerpTrack(play.ball_track, t)
    if (!ballCaught.current) {
      baseball.position.set(ballPos.x, ballPos.y, ballPos.z)
    }

    if (t < contactMs) {
      actualFielder.scene.position.set(actualStart.x, 0, actualStart.z)
      averageFielder.scene.position.set(ghostStart.x, 0, ghostStart.z)
      orientFielderTowardBall(actualFielder, landingPoint, ballPos)
      orientFielderTowardBall(averageFielder, landingPoint, ballPos)
    } else {
      const actualPos = lerpTrack(play.fielder_track, t)
      const aClamp = clampInsidePark(actualPos.x, actualPos.z, 0.4)
      actualFielder.scene.position.set(aClamp.x, 0, aClamp.z)
      const ghostPos = samplePolyline(ghostRoute, ghostProgress)
      const gClamp = clampInsidePark(ghostPos.x, ghostPos.z, 0.4)
      averageFielder.scene.position.set(gClamp.x, 0, gClamp.z)
      if (phase === 'running' || phase === 'caught') {
        orientFielderTowardBall(actualFielder, landingPoint, ballPos)
        orientFielderTowardBall(averageFielder, landingPoint, ballPos)
      }
    }

    const wantActualRun = phase === 'running' && t >= contactMs
    const wantAverageRun = phase === 'running' && t >= contactMs

    if (phase !== lastPhase.current || lastActualAnim.current === '' || t < contactMs) {
      if (phase === 'idle' || t < contactMs) {
        if (lastActualAnim.current !== 'StandingNeutral') {
          actualFielder.setAnimationState('StandingNeutral')
          lastActualAnim.current = 'StandingNeutral'
        }
        if (lastAverageAnim.current !== 'StandingNeutral') {
          averageFielder.setAnimationState('StandingNeutral')
          lastAverageAnim.current = 'StandingNeutral'
        }
        lastPhase.current = phase
      } else if (phase === 'running') {
        lastPhase.current = phase
        if (wantActualRun && lastActualAnim.current !== 'NewRunning') {
          actualFielder.setAnimationState('NewRunning')
          lastActualAnim.current = 'NewRunning'
        }
        if (wantAverageRun && lastAverageAnim.current !== 'NewRunning') {
          averageFielder.setAnimationState('NewRunning')
          lastAverageAnim.current = 'NewRunning'
        }
      } else if (phase === 'caught') {
        lastPhase.current = phase
        const endBall = play.ball_track[play.ball_track.length - 1]
        const fielderPos = actualFielder.scene.position
        const reach = Math.hypot(fielderPos.x - endBall.x, fielderPos.z - endBall.z)
        if (reach < 3.5) {
          const catchAnim = endBall.y > 1.5 ? 'CatchHI' : 'CatchMid'
          if (lastActualAnim.current !== catchAnim) {
            actualFielder.setAnimationState(catchAnim)
            try {
              actualFielder.attachBallToHand(baseball, 'L')
              ballCaught.current = true
            } catch {
              /* ignore */
            }
            lastActualAnim.current = catchAnim
          }
        } else if (lastActualAnim.current !== 'StandingNeutral') {
          actualFielder.setAnimationState('StandingNeutral')
          lastActualAnim.current = 'StandingNeutral'
        }
        if (lastAverageAnim.current !== 'StandingNeutral') {
          averageFielder.setAnimationState('StandingNeutral')
          lastAverageAnim.current = 'StandingNeutral'
        }
      }
    } else if (phase === 'running') {
      if (wantActualRun && lastActualAnim.current !== 'NewRunning') {
        actualFielder.setAnimationState('NewRunning')
        lastActualAnim.current = 'NewRunning'
      }
      if (wantAverageRun && lastAverageAnim.current !== 'NewRunning') {
        averageFielder.setAnimationState('NewRunning')
        lastAverageAnim.current = 'NewRunning'
      }
    }
  })

  // Camera sits behind both fielders and follows them in.
  // On deep wall catches we ease toward a safer watch angle so we do not clip the fence.
  useFrame(({ camera }) => {
    const actualPos = actualFielder.scene.position
    const avgPos = averageFielder.scene.position
    const mid = actualPos.clone().lerp(avgPos, 0.5)
    const ballPos = lerpTrack(play.ball_track, Math.min(clockMs, play.duration_ms))
    const sep = actualPos.distanceTo(avgPos)
    const startMid = actualStart.clone().lerp(ghostStart, 0.5)
    const startSep = Math.max(actualStart.distanceTo(ghostStart), 8)

    const behindDir = mid.clone()
    behindDir.y = 0
    if (behindDir.lengthSq() < 1e-6) behindDir.set(0, 0, 1)
    else behindDir.normalize()

    const actualR = Math.hypot(actualPos.x, actualPos.z)
    const avgR = Math.hypot(avgPos.x, avgPos.z)
    const deeperR = Math.max(actualR, avgR)
    const midR = Math.hypot(mid.x, mid.z)
    const landingR = Math.hypot(landingPoint.x, landingPoint.z)

    // pull back more when the two fielders are spread out
    // but never past the wall
    const desiredBack = Math.min(Math.max(12 + sep * 0.55, 12), 28)
    const maxCamRadius = oracleWallRadius(behindDir.x, behindDir.z) - 3
    const roomBehind = maxCamRadius - midR

    let back = Math.min(desiredBack, Math.max(0, roomBehind))
    let height = 2.7
    if (back < desiredBack) {
      height = 2.7 + (desiredBack - back) * 0.55
    }
    const minBackWanted = Math.max(2.5, deeperR - midR + 2.5)
    if (roomBehind >= minBackWanted) {
      back = Math.max(back, Math.min(desiredBack, minBackWanted))
    } else if (roomBehind < 4) {
      height = Math.max(height, 4.2 + Math.max(0, 4 - Math.max(0, roomBehind)) * 0.35)
    }

    const chaseCam = new Vector3(
      mid.x + behindDir.x * back,
      height,
      mid.z + behindDir.z * back,
    )
    const chaseClamped = clampInsidePark(chaseCam.x, chaseCam.z, 3)
    chaseCam.x = chaseClamped.x
    chaseCam.z = chaseClamped.z
    chaseCam.y = Math.max(2.6, chaseCam.y)

    // fallback view from behind the starting spots for deep catches
    const startBehind = startMid.clone()
    startBehind.y = 0
    if (startBehind.lengthSq() < 1e-6) startBehind.set(0, 0, 1)
    else startBehind.normalize()
    const watchBack = Math.min(Math.max(14 + startSep * 0.4, 14), 20)
    const watchCam = new Vector3(
      startMid.x + startBehind.x * watchBack,
      3.1,
      startMid.z + startBehind.z * watchBack,
    )
    const watchClamped = clampInsidePark(watchCam.x, watchCam.z, 3)
    watchCam.x = watchClamped.x
    watchCam.z = watchClamped.z

    const deepWallCatch = landingR >= 115
    const progress = play.duration_ms > 0 ? clockMs / play.duration_ms : 0
    const depthBlend = deepWallCatch
      ? Math.min(1, Math.max(0, (deeperR - 108) / 8))
      : 0
    const endBlend = deepWallCatch
      ? Math.min(1, Math.max(0, (progress - 0.45) / 0.35))
      : 0
    const watchBlend = Math.max(depthBlend, endBlend)

    const targetCam = chaseCam.clone().lerp(watchCam, watchBlend)

    const chaseFocus = mid.clone().lerp(landingPoint, 0.55)
    chaseFocus.x = chaseFocus.x * 0.85 + ballPos.x * 0.15
    chaseFocus.z = chaseFocus.z * 0.85 + ballPos.z * 0.15
    chaseFocus.y = Math.max(1.1, ballPos.y * 0.4)

    const watchFocus = landingPoint.clone()
    watchFocus.y = Math.max(1.2, ballPos.y * 0.35)
    watchFocus.x = watchFocus.x * 0.7 + actualPos.x * 0.3
    watchFocus.z = watchFocus.z * 0.7 + actualPos.z * 0.3

    const focus = chaseFocus.clone().lerp(watchFocus, watchBlend)

    camera.position.lerp(targetCam, 0.1)
    camera.lookAt(focus.x, focus.y, focus.z)
  })

  return (
    <group>
      <Park scene={parkScene} />
      <StartMarker position={actualStart} color={ACTUAL_GREEN} />
      <StartMarker position={ghostStart} color={AVERAGE_RED} />

      <RouteTrail points={actualFullRoute} color={ACTUAL_GREEN} opacity={0.22} lineWidth={2} trailKey="actual-full" />
      <RouteTrail
        points={actualTraveledRoute}
        color={ACTUAL_GREEN}
        opacity={0.95}
        lineWidth={4}
        trailKey={`actual-travel-${actualTraveledRoute.length}`}
      />
      <RouteTrail points={ghostRoute} color={AVERAGE_RED} opacity={0.2} lineWidth={2} trailKey="avg-full" />
      <RouteTrail
        points={averageTraveledRoute}
        color={AVERAGE_RED}
        opacity={0.95}
        lineWidth={4}
        trailKey={`avg-travel-${averageTraveledRoute.length}`}
      />

      <RouteTrail
        points={ballTrail}
        color={BALL_TRAIL_YELLOW}
        opacity={0.95}
        lineWidth={3}
        trailKey={`ball-${ballTrail.length}`}
      />

      <group ref={freeBallGroup}>
        <primitive object={baseball} />
      </group>
      <primitive object={actualFielder.scene}>
        <FielderLabel label={`ACTUAL · ${play.fielder_abbr}`} color={ACTUAL_GREEN} />
      </primitive>
      <primitive object={averageFielder.scene}>
        <FielderLabel label={`GHOST · ${play.fielder_abbr}`} color={AVERAGE_RED} />
      </primitive>

      <ambientLight intensity={2} />
      <object3D ref={lightTargetRef} position={light.TARGET} />
      <directionalLight
        ref={lightRef}
        intensity={3}
        castShadow
        shadow-mapSize-width={1024}
        shadow-mapSize-height={1024}
        position={light.POSITION}
        target={lightTargetRef.current ?? undefined}
      >
        <orthographicCamera near={0.01} far={5000} attach="shadow-camera" args={[-50, 50, 50, -50]} />
      </directionalLight>
    </group>
  )
}
