import { useEffect, useRef, useState } from 'react'
import ShiftReplayView from './ShiftReplayView'
import './css/Experience.css'

type Stage = 'welcome' | 'how' | 'viz'

function Credits({ showHonor = false }: { showHonor?: boolean }) {
  return (
    <footer className="credits">
      <p>Shirin Alapati · Ethan Nepo · Jacob Crumley</p>
      <p>San José State University · Team 227</p>
      {showHonor && <p>2026 SMT Data Challenge · Honorable Mention</p>}
      <p>Tracking data from the 2026 SMT Data Challenge.</p>
      <p>3D stadium, players, and animation code adapted from Solomon Gumball’s baseball-sim (MIT).</p>
    </footer>
  )
}

function Welcome({ onHow, onSkip }: { onHow: () => void; onSkip: () => void }) {
  return (
    <section className="screen" aria-labelledby="welcome-title">
      <div className="screen-inner">
        <p className="eyebrow">GAME OF INCHES</p>
        <h1 id="welcome-title" className="welcome-title">
          Welcome to a 3D Visualization
          <br />
          of the Impact of
          <br />
          Outfield Positioning
        </h1>
        <p className="lede">
          A great catch can start before the ball is hit.
          <br />
          See how an outfielder’s starting position can make the difference.
        </p>
        <div className="actions">
          <button type="button" className="primary-btn" onClick={onHow}>
            HOW IT WORKS
          </button>
          <button type="button" className="text-btn" onClick={onSkip}>
            Skip to visualization
          </button>
        </div>
        <p className="honor">2026 SMT Data Challenge · Honorable Mention</p>
        <Credits />
      </div>
    </section>
  )
}

function HowItWorks({ onBack, onCheck }: { onBack: () => void; onCheck: () => void }) {
  return (
    <section className="screen" aria-labelledby="how-title">
      <div className="screen-inner">
        <h1 id="how-title" className="how-title">
          Did the fielder win the play before it started?
        </h1>
        <p className="how-intro">
          These 3D replays show how an outfielder’s starting position can make a catch more likely.
          Each example compares the actual play with an illustrative “ghost” fielder starting from
          the league-average position for that outfield spot.
        </p>
        <div className="explain-row">
          <article className="explain-card">
            <h2>
              <span className="swatch swatch-green" aria-hidden="true" />
              Green: The actual play
            </h2>
            <p>Watch the outfielder’s recorded route from their actual starting position.</p>
          </article>
          <article className="explain-card">
            <h2>
              <span className="swatch swatch-red" aria-hidden="true" />
              Red: The comparison
            </h2>
            <p>A simulated ghost fielder starts from the league-average position, illustrating the extra ground they would need to cover.</p>
          </article>
          <article className="explain-card">
            <h2>
              <span className="swatch swatch-split" aria-hidden="true" />
              The positioning advantage
            </h2>
            <p>Compare estimated catch probabilities and the distance saved by starting closer to the catch location.</p>
          </article>
        </div>
        <p className="sim-note">
          The ghost route is a simulation, not a recorded play or a guarantee of what would have happened.
        </p>
        <details className="about">
          <summary>About the analysis</summary>
          <div className="about-body">
            <p>
              Our analysis examined 2,696 clean outfield catches across 251 Minor League games in the SMT dataset.
              We identified 363 catches (13.5%) that met our criteria for a positioning advantage.
              These are selected examples of positioning helping on completed catches, not an evaluation of every defensive alignment.
            </p>
            <p>
              Catch probabilities are estimates based on a published Statcast distance-and-opportunity-time chart, with an adjustment for backward movement.
              They are not official MLB probabilities for these plays.
            </p>
            <p>
              Distance saved compares the straight-line distance needed to reach the catch location from the league-average starting position with the distance needed from the actual starting position.
            </p>
            <p>
              The ghost route is constructed from the actual route and repositioned to start at the average location.
              Its movement is illustrative; it does not model every possible reaction, route, dive, jump, or wall interaction.
            </p>
            <p>
              The stadium and uniforms are presentation assets and do not identify the actual venue or teams for each play.
            </p>
          </div>
        </details>
        <div className="actions">
          <button type="button" className="primary-btn" onClick={onCheck}>
            CHECK IT OUT
          </button>
          <button type="button" className="text-btn" onClick={onBack}>
            Back
          </button>
        </div>
        <Credits showHonor />
      </div>
    </section>
  )
}

export default function Experience() {
  const [stage, setStage] = useState<Stage>('welcome')
  const [vizMounted, setVizMounted] = useState(false)
  const vizRef = useRef<HTMLDivElement>(null)

  const openViz = () => {
    setVizMounted(true)
    setStage('viz')
  }

  useEffect(() => {
    const node = vizRef.current
    if (!node) return
    if (stage === 'viz') node.removeAttribute('inert')
    else node.setAttribute('inert', '')
  }, [stage, vizMounted])

  return (
    <div className="experience">
      {vizMounted && (
        <div
          ref={vizRef}
          className={stage === 'viz' ? 'experience-viz' : 'experience-viz experience-viz--hidden'}
          aria-hidden={stage !== 'viz'}
        >
          <ShiftReplayView active={stage === 'viz'} onOpenGuide={() => setStage('how')} />
        </div>
      )}
      {stage === 'welcome' && <Welcome onHow={() => setStage('how')} onSkip={openViz} />}
      {stage === 'how' && <HowItWorks onBack={() => setStage('welcome')} onCheck={openViz} />}
    </div>
  )
}
